//! NEW mutable Main tone -> volume -> duck strip. Explicit Native author/output frames.
//! Main-thread clamp, authored-frame insertion pruning and render-time new-event clamp remain distinct. No inferred silent flag or app adoption.
#[path="../../rack-filter-normal/src/timeline.rs"]mod timeline;
#[path="../../rack-native/src/biquad.rs"]mod biquad;
#[path="../../rack-native/src/tail.rs"]mod tail;
#[cfg(feature="allocation-audit")]mod allocation;
const BLOCK:usize=2048;const CAP:usize=256;const MAX_FRAME:u64=1099511627648;
pub struct Engine{rate:f64,channels:usize,ready:bool,frame:u64,last_authored:f64,late:u64,clamped:u64,filtered:bool,bound:bool,accurate:[bool;2],lanes:[timeline::LiveTimeline;3],filter:biquad::Biquad,input:[[f32;BLOCK];2],output:[[f32;BLOCK];2],calls:u64,rejected:u64,peak:f64}
impl Engine{
 fn new(rate:f64,channels:usize,filtered:bool)->Option<Box<Self>>{if !rate.is_finite()||rate.fract()!=0.||!(8000. ..=192000.).contains(&rate)||!(1..=2).contains(&channels){return None;}Some(Box::new(Self{rate,channels,ready:false,frame:0,last_authored:-1.,late:0,clamped:0,filtered,bound:false,accurate:[false;2],lanes:std::array::from_fn(|i|timeline::LiveTimeline::new(if i==0{20000f64.min(rate/2.)}else{1.},CAP,rate)),filter:biquad::Biquad::default(),input:[[0.;BLOCK];2],output:[[0.;BLOCK];2],calls:0,rejected:0,peak:0.}))}
 fn command(&mut self,lane:usize,kind:usize,seconds:f64,value:f64,tau:f64,authored:f64)->bool{if !self.ready||lane>2||kind>3||kind==1||!seconds.is_finite()||seconds<0.||seconds>MAX_FRAME as f64/self.rate||!value.is_finite()||!tau.is_finite()||tau<0.||kind==2&&tau==0.||!authored.is_finite()||authored<0.||authored.fract()!=0.||authored%128.!=0.||authored>self.frame as f64||authored<self.last_authored||kind<3&&(!(0. ..=if lane==0{self.rate/2.}else if lane==1{4.}else{1.}).contains(&value)||!self.lanes[lane].available_at(1,authored)){self.rejected+=1;return false;}let time=seconds.max(authored/self.rate);if time!=seconds{self.clamped+=1;}self.lanes[lane].prune_for_insert(authored);if kind==3{self.lanes[lane].cancel(time*self.rate);}else{assert!(self.lanes[lane].add_seconds(time,kind as u32,value,tau));}if authored<self.frame as f64{self.late+=1;}self.last_authored=authored;true}
 fn initial(&mut self,lane:usize,value:f64)->bool{if self.ready||lane>2||!value.is_finite()||!(0. ..=if lane==0{self.rate/2.}else if lane==1{4.}else{1.}).contains(&value){self.rejected+=1;return false;}self.lanes[lane].intrinsic(value);true}
 fn render(&mut self,n:usize)->bool{if !self.ready||n>BLOCK||self.frame+n as u64>MAX_FRAME||(0..self.channels).any(|c|self.input[c][..n].iter().any(|x|!x.is_finite())){self.rejected+=1;return false;}self.peak=0.;for i in 0..n{if self.frame%128==0{for j in 0..2{self.accurate[j]=self.lanes[j+1].accurate(self.frame);}for lane in &mut self.lanes{lane.prepare(self.frame,self.rate);}}let at=self.frame as usize%128;let x=[self.input[0][i],if self.channels==2{self.input[1][i]}else{0.}];let y=if self.filtered{self.filter.sample(x,self.channels,0,self.lanes[0].output[at]as f64,0.5,0.,self.rate)}else{x};for c in 0..self.channels{let vg=self.lanes[1].output[at];let dg=self.lanes[2].output[at];let v=if !self.accurate[0]&&vg==0.{0.}else{y[c]*vg};let v=if !self.accurate[1]&&dg==0.{0.}else{v*dg};if !v.is_finite(){self.rejected+=1;return false;}self.output[c][i]=v;self.peak=self.peak.max(v.abs()as f64);}self.frame+=1;if self.frame%128==0{self.filter.end_quantum();}}self.calls+=1;true}
}
#[no_mangle]pub extern "C" fn main_strip_live_api()->u32{1}
#[no_mangle]pub extern "C" fn main_strip_live_new(rate:f64,channels:usize,filtered:u32)->*mut Engine{if filtered>1{return std::ptr::null_mut();}Engine::new(rate,channels,filtered==1).map(Box::into_raw).unwrap_or(std::ptr::null_mut())}
#[no_mangle]pub unsafe extern "C" fn main_strip_live_free(p:*mut Engine){if !p.is_null(){drop(Box::from_raw(p));}}
#[no_mangle]pub extern "C" fn main_strip_live_initial(p:&mut Engine,lane:usize,value:f64)->u32{p.initial(lane,value)as u32}
#[no_mangle]pub extern "C" fn main_strip_live_command(p:&mut Engine,lane:usize,kind:usize,seconds:f64,value:f64,tau:f64,authored:f64)->u32{p.command(lane,kind,seconds,value,tau,authored)as u32}
#[no_mangle]pub extern "C" fn main_strip_live_prepare(p:&mut Engine,frame:f64)->u32{if p.ready||!frame.is_finite()||frame<0.||frame>MAX_FRAME as f64||frame.fract()!=0.||frame%128.!=0.{p.rejected+=1;return 0;}p.frame=frame as u64;p.ready=true;1}
#[no_mangle]pub extern "C" fn main_strip_live_first_frame(p:&mut Engine,frame:f64)->u32{if !p.ready||p.bound||p.calls!=0||!frame.is_finite()||frame<p.frame as f64||frame>MAX_FRAME as f64||frame.fract()!=0.||frame%128.!=0.{p.rejected+=1;return 0;}p.frame=frame as u64;p.bound=true;1}
#[no_mangle]pub extern "C" fn main_strip_live_input(p:&mut Engine,ch:usize)->*mut f32{p.input.get_mut(ch).map(|p|p.as_mut_ptr()).unwrap_or(std::ptr::null_mut())}
#[no_mangle]pub extern "C" fn main_strip_live_output(p:&Engine,ch:usize)->*const f32{p.output.get(ch).map(|p|p.as_ptr()).unwrap_or(std::ptr::null())}
#[no_mangle]pub extern "C" fn main_strip_live_render(p:&mut Engine,n:usize)->u32{p.render(n)as u32}
#[no_mangle]pub extern "C" fn main_strip_live_stat(p:&Engine,key:usize)->f64{match key{0=>p.frame as f64,1=>p.peak,2=>p.calls as f64,3=>p.rejected as f64,4=>p.last_authored,5=>p.late as f64,6=>p.clamped as f64,7=>p.filtered as u32 as f64,_=>f64::NAN}}
